const KEY='ritm-v1', $=s=>document.querySelector(s), names=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'], periods={morning:'☀ Утро',day:'◉ День',evening:'☾ Вечер'};
const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, parse=s=>new Date(s+'T12:00:00'), shift=(s,n)=>{const d=parse(s);d.setDate(d.getDate()+n);return key(d)}, today=()=>key(new Date()), weekday=s=>(parse(s).getDay()+6)%7, monday=s=>shift(s,-weekday(s));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={habits:[],logs:{}},selected=today(),view='today',editing=null,month=today().slice(0,7),archive=false,timer;
function valid(s){return s&&Array.isArray(s.habits)&&s.habits.length<=500&&s.logs&&typeof s.logs==='object'&&!Array.isArray(s.logs)&&new Set(s.habits.map(h=>h.id)).size===s.habits.length&&s.habits.every(h=>typeof h.id==='string'&&/^[a-zA-Z0-9-]+$/.test(h.id)&&typeof h.name==='string'&&h.name.length>0&&h.name.length<=70&&['check','count','minutes'].includes(h.type)&&Number.isFinite(h.target)&&h.target>=1&&h.target<=100000&&Object.hasOwn(periods,h.period)&&typeof h.icon==='string'&&h.icon.length<=10&&['days','weekly'].includes(h.schedule)&&Array.isArray(h.days)&&h.days.every(d=>Number.isInteger(d)&&d>=0&&d<=6)&&h.days.length>0&&Number.isInteger(h.frequency)&&h.frequency>=1&&h.frequency<=7&&/^\d{4}-\d{2}-\d{2}$/.test(h.created))&&Object.entries(s.logs).every(([d,v])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&v&&typeof v==='object'&&!Array.isArray(v)&&Object.entries(v).every(([id,n])=>s.habits.some(h=>h.id===id)&&Number.isFinite(n)&&n>=0&&n<=100000));}
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(!valid(saved))throw Error();state=saved;}}catch{setTimeout(()=>toast('Не удалось прочитать данные. Восстановите резервную копию.'),100)}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return true}catch{toast('Не удалось сохранить данные. Проверьте доступ к хранилищу браузера.');return false}}
const value=(h,d)=>state.logs[d]?.[h.id]||0, done=(h,d)=>value(h,d)>=h.target;
function weekCount(h,d){const start=monday(d);return Array.from({length:7},(_,i)=>shift(start,i)).filter(x=>x<=today()&&done(h,x)).length}
function scheduled(h,d){return d>=h.created&&(!h.archivedAt||d<h.archivedAt)&&(h.schedule==='weekly'||h.days.includes(weekday(d)))}
function tasks(d){return state.habits.filter(h=>scheduled(h,d))}
function totals(d){const list=tasks(d);return {total:list.length,complete:list.filter(h=>done(h,d)).length}}
function weekStats(){let target=0,complete=0;const start=monday(today());for(const h of state.habits){if(h.schedule==='weekly'){if(h.created<=today()&&(!h.archivedAt||h.archivedAt>start)){target+=h.frequency;complete+=Math.min(weekCount(h,today()),h.frequency)}}else for(let i=0;i<7;i++){const d=shift(start,i);if(d<=today()&&scheduled(h,d)){target++;if(done(h,d))complete++}}}return {target,complete,percent:target?Math.round(complete/target*100):0}}
function streak(h){let count=0,best=0,current=0;if(h.schedule==='weekly'){for(let start=monday(h.created);start<=monday(today());start=shift(start,7)){if(h.archivedAt&&start>=h.archivedAt)break;const success=weekCount(h,start)>=h.frequency;count=success?count+1:start===monday(today())?count:0;best=Math.max(best,count)}return {current:count,best,unit:'нед.'}}for(let d=h.created;d<=today();d=shift(d,1)){if(!scheduled(h,d))continue;if(done(h,d)){count++;best=Math.max(best,count)}else if(d!==today())count=0}current=count;return {current,best,unit:'дн.'}}
function change(id,amount){const h=state.habits.find(h=>h.id===id);if(!h||selected>today()||!scheduled(h,selected))return;const next=structuredClone(state);next.logs[selected]??={};next.logs[selected][id]=Math.min(100000,Math.max(0,amount));save(next)}
function habitRow(h,management=false){const complete=done(h,selected),v=value(h,selected),s=streak(h),unit=h.type==='minutes'?'мин.':h.type==='count'?'раз':'',schedule=h.schedule==='weekly'?`${weekCount(h,selected)} / ${h.frequency} на неделе`:h.days.length===7?'Каждый день':h.days.map(d=>names[d]).join(', ');return `<article class="habit ${complete?'done':''}"><div class="habit-icon">${escape(h.icon)}</div><div class="habit-info"><strong>${escape(h.name)}</strong><small>${management?escape(schedule):h.type==='check'?'Один маленький шаг':`${v} / ${h.target} ${unit}`} ${s.current?' · '+s.current+' '+s.unit+' подряд':''}</small></div>${management?`<button class="archive-button" data-archive="${h.id}">${h.archivedAt?'Вернуть':'В архив'}</button>`:h.type!=='check'?`<div class="quantity"><button data-minus="${h.id}" aria-label="Уменьшить: ${escape(h.name)}">−</button><span>${v}/${h.target}</span><button data-plus="${h.id}" aria-label="Добавить: ${escape(h.name)}">+</button></div>`:''}${management?'':`<button class="complete" data-check="${h.id}" aria-pressed="${complete}" aria-label="${complete?'Отменить':'Выполнить'}: ${escape(h.name)}">✓</button>`}<button class="edit" data-edit="${h.id}" aria-label="Редактировать: ${escape(h.name)}">⋯</button></article>`}
function weekStrip(){const start=monday(selected);return `<div class="section-title"><button data-week="-7" aria-label="Предыдущая неделя">←</button><small>${parse(start).toLocaleDateString('ru',{day:'numeric',month:'long'})} — ${parse(shift(start,6)).toLocaleDateString('ru',{day:'numeric',month:'long'})}</small><button data-week="7" aria-label="Следующая неделя" ${shift(start,7)>today()?'disabled':''}>→</button></div><div class="week">${Array.from({length:7},(_,i)=>{const d=shift(start,i);return `<button class="day ${selected===d?'selected':''}" data-date="${d}" ${d>today()?'disabled':''}><span>${names[i]}</span><b>${parse(d).getDate()}</b><i></i></button>`}).join('')}</div>`}
function side(){const s=weekStats(),all=Object.values(state.logs).reduce((n,logs)=>n+state.habits.filter(h=>(logs[h.id]||0)>=h.target).length,0);return `<div class="right-column"><section class="card"><h2>Эта неделя</h2><div class="big-number">${s.percent}% <small>от плана</small></div><div class="bars">${Array.from({length:7},(_,i)=>{const d=shift(monday(today()),i),t=totals(d),p=t.total?t.complete/t.total*100:0;return `<div class="bar-column"><div class="bar ${d===today()?'today':''}" style="height:${p}%" title="${t.complete} из ${t.total}"></div>${names[i]}</div>`}).join('')}</div><p class="muted">${s.complete} из ${s.target} выполнено · дневные цели до сегодня, недельные — за всю неделю</p></section><section class="card"><h2>Маленькие победы</h2><div class="stat-line"><span>Выполнено всего</span><b>${all}</b></div><div class="stat-line"><span>Активных привычек</span><b>${state.habits.filter(h=>!h.archivedAt).length}</b></div></section><section class="card tip"><div class="tip-icon">✧</div><strong>Регулярность важнее рекордов</strong><p>Пропустили день? Просто начните снова. Уже сделанные шаги остаются с вами.</p></section></div>`}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const label={today:'Сегодня',stats:'Статистика',habits:'Мои привычки'}[view];$('#page-label').textContent=label;$('#date-label').textContent=parse(selected).toLocaleDateString('ru',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#title').innerHTML={today:'Каждый шаг считается<span>.</span>',stats:'Посмотрите, как далеко вы пришли<span>.</span>',habits:'То, что делает день лучше<span>.</span>'}[view];$('#subtitle').textContent={today:'Немного внимания себе — каждый день.',stats:'Ваш прогресс складывается из маленьких действий.',habits:'Выберите свой темп. Всё остальное придёт со временем.'}[view];if(view==='today'){const t=totals(selected),list=tasks(selected);$('#content').innerHTML=`<div class="dashboard"><div><section class="summary"><div><div class="eyebrow">${selected===today()?'ВАШ СЕГОДНЯШНИЙ РИТМ':'ПРОГРЕСС ЗА ДЕНЬ'}</div><h2>${t.total?`${t.complete} из ${t.total} выполнено`:'Начнём с малого'}</h2><p>${t.total?(t.complete===t.total?'Всё получилось. Этот день — ваша маленькая победа.':'Каждая отметка — время, которое вы подарили себе.'):'Добавьте первую привычку и сделайте шаг к себе.'}</p></div><div class="ring" style="--progress:${t.total?t.complete/t.total*100:0}%"><div><b>${t.total?Math.round(t.complete/t.total*100):0}%</b><small>за день</small></div></div></section>${weekStrip()}<div class="section-title"><h2>${selected===today()?'Мои привычки на сегодня':'Привычки на выбранный день'}</h2><small>${list.length} в плане</small></div>${list.length?Object.entries(periods).map(([p,title])=>{const rows=list.filter(h=>h.period===p).sort((a,b)=>done(a,selected)-done(b,selected));return rows.length?`<div class="period-title">${title}</div>${rows.map(h=>habitRow(h)).join('')}`:''}).join(''):`<div class="empty">${state.habits.length?'На этот день привычек нет. Можно отдохнуть.':'Ваш новый ритм начинается с одной привычки.<br><button class="primary" data-create>＋ Добавить первую привычку</button>'}</div>`}</div>${side()}</div>`}else if(view==='habits'){$('#content').innerHTML=`<div class="section-title"><h2>${archive?'Архив':'Активные привычки'}</h2><button class="archive-button" id="toggle-archive">${archive?'Показать активные':'Открыть архив'}</button></div>${state.habits.filter(h=>!!h.archivedAt===archive).map(h=>habitRow(h,true)).join('')||'<div class="empty">Здесь пока нет привычек.</div>'}`}else{const first=month+'-01',n=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();$('#content').innerHTML=`<div class="stats-grid"><section class="card"><div class="month-nav"><button data-month="-1" aria-label="Предыдущий месяц">←</button><h2>${parse(first).toLocaleDateString('ru',{month:'long',year:'numeric'})}</h2><button data-month="1" aria-label="Следующий месяц" ${month>=today().slice(0,7)?'disabled':''}>→</button></div><div class="calendar">${names.map(n=>`<span>${n}</span>`).join('')}${'<span></span>'.repeat(weekday(first))}${Array.from({length:n},(_,i)=>{const d=shift(first,i),t=totals(d);return `<button data-date="${d}" class="${t.complete?(t.complete===t.total?'full':'has'):''}" ${d>today()?'disabled':''} title="${t.complete} из ${t.total}">${i+1}</button>`}).join('')}</div><p class="muted">Нажмите на день, чтобы посмотреть или исправить отметки.</p></section><section class="card"><h2>Серии привычек</h2>${state.habits.map(h=>{const s=streak(h);return `<div class="stat-line"><span>${escape(h.icon)} ${escape(h.name)}</span><b>${s.current} ${s.unit}</b></div><p class="muted">Лучшая серия: ${s.best} ${s.unit}</p>`}).join('')||'<p class="muted">Добавьте привычку — здесь появятся ваши серии.</p>'}</section></div>`}}
function openEditor(id){editing=id||null;const h=state.habits.find(h=>h.id===id),f=$('#habit-form');f.reset();$('#dialog-title').textContent=h?'Редактировать привычку':'Новая привычка';for(const k of ['name','type','target','period','icon','schedule','frequency'])if(h)f.elements[k].value=h[k];$('#days').innerHTML='<legend>Дни недели</legend>'+names.map((n,i)=>`<label><input type="checkbox" value="${i}" ${(h?h.days.includes(i):true)?'checked':''}><span>${n}</span></label>`).join('');scheduleFields();$('#editor').showModal();f.elements.name.focus()}
function scheduleFields(){const weekly=$('#habit-form').elements.schedule.value==='weekly';$('#days').hidden=weekly;$('#weekly-label').hidden=!weekly;const check=$('#habit-form').elements.type.value==='check';$('#habit-form').elements.target.disabled=check;if(check)$('#habit-form').elements.target.value=1}
$('#habit-form').addEventListener('change',scheduleFields);$('#habit-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target,days=[...$('#days').querySelectorAll('input:checked')].map(i=>Number(i.value)),name=f.elements.name.value.trim();if(!name)return toast('Введите название привычки.');if(!days.length&&f.elements.schedule.value==='days')return toast('Выберите хотя бы один день.');const next=structuredClone(state),old=next.habits.find(h=>h.id===editing),h={id:editing||crypto.randomUUID(),name,type:f.elements.type.value,target:Number(f.elements.target.value),period:f.elements.period.value,icon:f.elements.icon.value,schedule:f.elements.schedule.value,frequency:Number(f.elements.frequency.value),days:days.length?days:[0,1,2,3,4,5,6],created:old?.created||today(),archivedAt:old?.archivedAt||null};if(old)Object.assign(old,h);else next.habits.push(h);if(!valid(next))return toast('Проверьте цель и расписание.');if(save(next)){$('#editor').close();toast('Привычка сохранена')}});
$('#add').onclick=()=>openEditor();$('#close').onclick=()=>$('#editor').close();document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view){view=d.view;render()}if(d.create!==undefined)openEditor();if(d.date){selected=d.date;view='today';render()}if(d.week){selected=shift(selected,Number(d.week));if(selected>today())selected=today();render()}if(d.month){const date=parse(month+'-01');date.setMonth(date.getMonth()+Number(d.month));month=key(date).slice(0,7);render()}if(d.edit)openEditor(d.edit);for(const action of ['plus','minus','check'])if(d[action]){const h=state.habits.find(h=>h.id===d[action]);change(h.id,action==='check'?(done(h,selected)?0:h.target):value(h,selected)+(action==='plus'?1:-1))}if(d.archive){const next=structuredClone(state),h=next.habits.find(h=>h.id===d.archive);h.archivedAt=h.archivedAt?null:today();save(next)}if(b.id==='toggle-archive'){archive=!archive;render()}});
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`ritm-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия скачана')};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error();const data=JSON.parse(await file.text());if(!valid(data))throw Error();if(confirm('Заменить текущие привычки и отметки данными из этой копии?')){if(save(data))toast('Данные восстановлены')}}catch{toast('Файл не подходит. Выберите резервную копию Ритма.')}finally{e.target.value=''}};
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const next=JSON.parse(e.newValue);if(valid(next)){state=next;render()}}catch{}});
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_habits',description:'Read habits and progress for the selected date.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({date:selected,habits:tasks(selected).map(h=>({id:h.id,name:h.name,target:h.target,value:value(h,selected)}))})})).catch(()=>{})}catch{}
render();
